	private static void assertSameOutcome(String sparql, ResultOrder order, EvaluationResult expected,
			EvaluationResult actual) {
		if (expected.succeeded() != actual.succeeded()) {
			throw new AssertionError(actual.arm() + " success/failure differs from MemoryStore for:\n" + sparql
					+ "\nMemoryStore=" + expected + "\nactual=" + actual);
		}
		if (!expected.succeeded()) {
			if (expected.failure().category() != actual.failure().category()) {
				throw new AssertionError(actual.arm() + " failure category differs from MemoryStore for:\n" + sparql
						+ "\nMemoryStore=" + expected.failure() + "\nactual=" + actual.failure());
			}
			return;
		}
		if (!expected.resultBindingNames().equals(actual.resultBindingNames())) {
			throw new AssertionError(actual.arm() + " result binding names differ from MemoryStore for:\n" + sparql
					+ "\nMemoryStore=" + expected.resultBindingNames() + "\nactual=" + actual.resultBindingNames());
		}
		Object expectedRows = order == ResultOrder.ORDERED ? expected.rows() : expected.multiset();
		Object actualRows = order == ResultOrder.ORDERED ? actual.rows() : actual.multiset();
		if (!expectedRows.equals(actualRows)) {
			throw new AssertionError(actual.arm() + " " + order.name().toLowerCase(Locale.ROOT)
					+ " answers differ from MemoryStore for:\n" + sparql + "\nMemoryStore=" + expectedRows
					+ "\nactual=" + actualRows);
		}
	}

	private static CanonicalBindingSet canonicalize(BindingSet bindingSet) {
		TreeSet<String> declaredNames = new TreeSet<>(bindingSet.getBindingNames());
		TreeMap<String, Value> iteratedBindings = new TreeMap<>();
		for (Binding binding : bindingSet) {
			Value previous = iteratedBindings.put(binding.getName(), binding.getValue());
			if (previous != null) {
				throw new AssertionError("binding iteration repeated name " + binding.getName() + ": " + bindingSet);
			}
		}
		if (bindingSet.size() != iteratedBindings.size() || !declaredNames.equals(iteratedBindings.keySet())) {
			throw new AssertionError("binding domain disagreement: size=" + bindingSet.size() + ", names="
					+ declaredNames + ", iteration=" + iteratedBindings.keySet() + ", row=" + bindingSet);
		}
		List<CanonicalBinding> bindings = new ArrayList<>(iteratedBindings.size());
		for (Map.Entry<String, Value> entry : iteratedBindings.entrySet()) {
			if (entry.getValue() == null || bindingSet.getValue(entry.getKey()) == null) {
				throw new AssertionError("bound name has no value: " + entry.getKey() + " in " + bindingSet);
			}
			bindings.add(new CanonicalBinding(entry.getKey(), canonicalize(entry.getValue())));
		}
		return new CanonicalBindingSet(bindings);
	}

	private static CanonicalTerm canonicalize(Value value) {
		if (value instanceof IRI iri) {
			return new CanonicalIri(iri.stringValue());
		}
		if (value instanceof BNode bNode) {
			return new CanonicalBNode(bNode.getID());
		}
		if (value instanceof Literal literal) {
			Optional<String> language = literal.getLanguage().map(tag -> tag.toLowerCase(Locale.ROOT));
			return new CanonicalLiteral(literal.getLabel(), literal.getDatatype().stringValue(), language,
					literal.getBaseDirection());
		}
		if (value instanceof TripleTerm tripleTerm) {
			return new CanonicalTripleTerm(canonicalize(tripleTerm.getSubject()),
					new CanonicalIri(tripleTerm.getPredicate().stringValue()), canonicalize(tripleTerm.getObject()));
		}
		throw new AssertionError("unsupported RDF value implementation: " + value.getClass().getName());
	}

	private static ExceptionCategory categoryOf(Throwable failure) {
		if (hasCause(failure, QueryInterruptedException.class) || hasCause(failure, CancellationException.class)
				|| hasCause(failure, InterruptedException.class)) {
			return ExceptionCategory.CANCELLATION;
		}
		if (hasCause(failure, MalformedQueryException.class)) {
			return ExceptionCategory.MALFORMED_QUERY;
		}
		if (hasCause(failure, UnsupportedQueryLanguageException.class)) {
			return ExceptionCategory.UNSUPPORTED_QUERY_LANGUAGE;
		}
		if (hasCause(failure, QueryEvaluationException.class)) {
			return ExceptionCategory.QUERY_EVALUATION;
		}
		if (hasCause(failure, RepositoryException.class)) {
			return ExceptionCategory.REPOSITORY;
		}
		if (hasCause(failure, SailException.class)) {
			return ExceptionCategory.SAIL;
		}
		if (hasCause(failure, IllegalArgumentException.class)) {
			return ExceptionCategory.INVALID_ARGUMENT;
		}
		return ExceptionCategory.RUNTIME;
	}

	private static boolean hasCause(Throwable failure, Class<? extends Throwable> type) {
		Set<Throwable> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Throwable current = failure; current != null && visited.add(current); current = current.getCause()) {
			if (type.isInstance(current)) {
				return true;
			}
		}
		return false;
	}

	private static <T> T withNativeEngineProperty(Boolean enabled, Supplier<T> action) {
		synchronized (NATIVE_ENGINE_PROPERTY_LOCK) {
			String previous = System.getProperty(NATIVE_ENGINE_PROPERTY);
			try {
				if (enabled != null) {
					System.setProperty(NATIVE_ENGINE_PROPERTY, enabled.toString());
				}
				return action.get();
			} finally {
				if (enabled != null) {
					restoreProperty(NATIVE_ENGINE_PROPERTY, previous);
				}
			}
		}
	}

	private static void restoreProperty(String name, String previous) {
		if (previous == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, previous);
		}
	}

