	/** Builds and identically loads all four independent repositories. */
	public static final class Builder {
		private final Path dataRoot;
		private DataLoader dataLoader;
		private boolean built;

		private Builder(Path dataRoot) {
			this.dataRoot = Objects.requireNonNull(dataRoot, "dataRoot");
		}

		public Builder load(DataLoader dataLoader) {
			this.dataLoader = Objects.requireNonNull(dataLoader, "dataLoader");
			return this;
		}

		public IndependentSparqlOracle build() throws Exception {
			if (built) {
				throw new IllegalStateException("builder has already created an oracle");
			}
			built = true;
			DataLoader loader = Objects.requireNonNull(dataLoader, "dataLoader");
			Files.createDirectories(dataRoot);
			EnumMap<Arm, ArmRuntime> runtimes = new EnumMap<>(Arm.class);
			try {
				addAndLoad(runtimes, Arm.MEMORY_STANDARD, buildMemoryStandard(), loader);
				addAndLoad(runtimes, Arm.LMDB_STANDARD_FACTORY,
						buildLmdbStandardFactory(dataRoot.resolve("lmdb-standard-factory")), loader);
				addAndLoad(runtimes, Arm.LMDB_OPTIMIZER_NATIVE_DISABLED,
						buildLmdbAutomatic(dataRoot.resolve("lmdb-native-disabled"), false), loader);
				addAndLoad(runtimes, Arm.LMDB_PRODUCTION,
						buildLmdbAutomatic(dataRoot.resolve("lmdb-production"), true), loader);
				return new IndependentSparqlOracle(runtimes);
			} catch (Exception failure) {
				closeAfterBuildFailure(runtimes, failure);
				throw failure;
			} catch (Error failure) {
				closeAfterBuildFailure(runtimes, failure);
				throw failure;
			}
		}

		private static ArmRuntime buildMemoryStandard() {
			MemoryStore store = new MemoryStore();
			return new ArmRuntime(new SailRepository(store), factoryType(store.getEvaluationStrategyFactory()), null);
		}

		private static ArmRuntime buildLmdbStandardFactory(Path dataDirectory) {
			LmdbStore store = new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig());
			store.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory());
			return new ArmRuntime(new SailRepository(store), factoryType(store.getEvaluationStrategyFactory()), null);
		}

		private static ArmRuntime buildLmdbAutomatic(Path dataDirectory, boolean nativeEnabled) {
			LmdbStore store = new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig());
			return new ArmRuntime(new SailRepository(store), factoryType(store.getEvaluationStrategyFactory()),
					nativeEnabled);
		}

		@SuppressWarnings("unchecked")
		private static Class<? extends EvaluationStrategyFactory> factoryType(EvaluationStrategyFactory factory) {
			return (Class<? extends EvaluationStrategyFactory>) factory.getClass();
		}

		private static void addAndLoad(EnumMap<Arm, ArmRuntime> runtimes, Arm arm, ArmRuntime runtime,
				DataLoader loader) throws Exception {
			runtimes.put(arm, runtime);
			try (RepositoryConnection connection = runtime.repository.getConnection()) {
				connection.begin();
				try {
					loader.load(connection);
					connection.commit();
				} catch (Exception | Error failure) {
					if (connection.isActive()) {
						try {
							connection.rollback();
						} catch (RuntimeException rollbackFailure) {
							if (rollbackFailure != failure) {
								failure.addSuppressed(rollbackFailure);
							}
						}
					}
					throw failure;
				}
			}
		}

		private static void closeAfterBuildFailure(EnumMap<Arm, ArmRuntime> runtimes, Throwable primary) {
			Arm[] values = Arm.values();
			for (int index = values.length - 1; index >= 0; index--) {
				ArmRuntime runtime = runtimes.get(values[index]);
				if (runtime != null) {
					try {
						runtime.repository.shutDown();
					} catch (RuntimeException closeFailure) {
						if (closeFailure != primary) {
							primary.addSuppressed(closeFailure);
						}
					}
				}
			}
		}
	}
